<style>
.kudia-page{--kudia-blue:#00ace4;--kudia-navy:#032d43;display:grid;gap:22px}.kudia-hero{position:relative;overflow:hidden;border-radius:24px;padding:30px;background:linear-gradient(120deg,#033349,#052135);color:#fff;display:flex;align-items:center;justify-content:space-between;gap:24px}.kudia-hero h1{font-size:29px;margin:0 0 6px}.kudia-hero p{margin:0;color:#b8d5e2}.kudia-wordmark{font:900 46px/1 sans-serif;letter-spacing:3px;color:#00b8e9}.kudia-nav{display:flex;flex-wrap:wrap;gap:9px}.kudia-nav a,.kudia-page .btn{display:inline-block;text-decoration:none;padding:11px 18px;border-radius:12px;background:var(--surface);border:1px solid var(--border);color:var(--text);font-weight:700}.kudia-nav a.active,.kudia-page .btn.primary{background:#00a9e0;color:#fff;border-color:#00a9e0}.kudia-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.kudia-stat,.kudia-panel{border:1px solid var(--border);background:var(--surface);border-radius:20px;padding:23px}.kudia-stat span{display:block;color:var(--text-soft);font-size:13px}.kudia-stat strong{display:block;margin-top:10px;font-size:28px;color:var(--text)}.kudia-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.kudia-toolbar form{display:flex;gap:8px}.kudia-toolbar h2{margin:0}.kudia-table{width:100%;border-collapse:collapse}.kudia-table th{text-align:right;color:var(--text-soft);font-size:12px}.kudia-table th,.kudia-table td{padding:15px 10px;border-bottom:1px solid var(--border)}.kudia-table a{color:#00a1d5;text-decoration:none;font-weight:800}.kudia-pill{border-radius:25px;padding:5px 11px;font-size:12px;background:#e5f6fb;color:#006a89}.kudia-pill.cancelled{background:#fee2e2;color:#b91c1c}.kudia-empty{text-align:center;padding:55px 20px;color:var(--text-soft)}.kudia-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.kudia-field label{display:block;margin-bottom:7px;font-weight:700}.kudia-field small{display:block;color:var(--text-soft);margin-top:5px}.kudia-field.wide{grid-column:1/-1}.kudia-line{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr auto;gap:10px;align-items:end;border:1px solid var(--border);border-radius:15px;padding:16px;margin-bottom:12px;background:var(--surface-soft)}.kudia-line input,.kudia-line textarea{min-width:0;width:100%}.kudia-line label{font-size:12px;display:block;margin-bottom:5px}.kudia-line .details{margin-top:7px}.kudia-remove{background:#fee2e2!important;color:#b91c1c!important;border:0;border-radius:9px;padding:10px}.kudia-totals{margin-top:18px;display:grid;gap:10px;max-width:370px;margin-inline-start:auto}.kudia-totals div{display:flex;justify-content:space-between;gap:20px}.kudia-totals .grand{border-top:2px solid #00ace4;padding-top:12px;font-size:21px;font-weight:900}.kudia-errors{background:#fee2e2;color:#991b1b;padding:18px;border-radius:15px}.kudia-cancel{margin-top:24px;border:1px solid #f4c6c6;padding:20px;border-radius:16px}.kudia-invoice-frame{width:100%;height:1000px;border:1px solid var(--border);border-radius:20px;background:#fff}@media(max-width:1000px){.kudia-line{grid-template-columns:repeat(2,minmax(0,1fr))}.kudia-line>div:first-child{grid-column:1/-1}}@media(max-width:600px){.kudia-form-grid,.kudia-stats{grid-template-columns:1fr}.kudia-hero{padding:24px;align-items:flex-start;flex-direction:column}.kudia-wordmark{font-size:34px}.kudia-invoice-frame{height:760px}}
</style>
